  const setAt = { ...(p.setAt || {}) };
  for (const k of Object.keys(fields || {})) { out[k] = fields[k]; setAt[k] = now; }
  out.setAt = setAt;
  out.rev = (+p.rev || 0) + 1;
  out.phaseLog = Array.isArray(out.phaseLog) ? out.phaseLog.slice() : [];
  if (logEntry) out.phaseLog.push({ id: _freshId("ph_"), at: now, ...logEntry });
