    const declKind = (p.rid && /^steppush_/.test(p.rid)) ? "steppush" : (p.rid && /^volpush_/.test(p.rid)) ? "volpush" : (p.rid && /^volroll_/.test(p.rid)) ? "volroll" : ((p.apply && p.apply.kind) || "default");
