      const dSteps = input.steps != null && stepRef != null ? ((input.steps - stepRef) * perStepKcal * 7) / edWhatIf : 0;
      const dCal = input.cal != null && calRef != null ? ((calRef - input.cal) * 7) / edWhatIf : 0;
